#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-1d.h"

/* Include the Exo-generated kernel header. */
#include "generated/jacobi-1d/jacobi-1d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i + 2) / n;
      B[i] = ((DATA_TYPE) i + 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# ---------------------------------------------------------------------------
# Base Jacobi‑1D kernel: straightforward two-sweep 3-point stencil.
#   - A is the primary state (input/output).
#   - B is a temporary buffer (not live at kernel exit).
#   - A[0] and A[n-1] are never written and remain equal to their
#     initialized boundary values.
# ---------------------------------------------------------------------------
@proc
def kernel_jacobi_1d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n] @ DRAM,
    B: DATA_TYPE[n] @ DRAM,
):
    # We update only the interior points 1 .. n-2.
    assert n > 2

    # Hoist the Jacobi weight into a scalar so it is loaded once and
    # kept in a register, instead of re-materializing the literal.
    w: DATA_TYPE
    w = 0.33333

    for t in seq(0, tsteps):
        # Sweep 1: compute B from the current A.
        # Each B[i] depends only on A[i-1], A[i], A[i+1].
        for i in seq(1, n - 1):
            B[i] = w * (A[i - 1] + A[i] + A[i + 1])

        # Sweep 2: compute new A from B.
        # Each A[i] depends only on B[i-1], B[i], B[i+1].
        for i in seq(1, n - 1):
            A[i] = w * (B[i - 1] + B[i] + B[i + 1])


# ---------------------------------------------------------------------------
# Scheduling: exploit thread-level parallelism in the spatial dimension.
#
# For a fixed time step t:
#   - In the B <- A sweep, all iterations over i are independent:
#       * A is read-only in this loop.
#       * Each iteration writes a distinct B[i].
#   - In the A <- B sweep, all iterations over i are independent:
#       * B is read-only in this loop.
#       * Each iteration writes a distinct A[i].
#
# Therefore each "for i" loop can be safely parallelized.  The two
# sweeps remain in sequence, so all B updates at time t complete
# before any A updates at time t start, preserving Jacobi semantics.
# ---------------------------------------------------------------------------

kernel_jacobi_1d_sched = kernel_jacobi_1d_base

# Parallelize the first sweep over i (B <- A).
loop_i0 = kernel_jacobi_1d_sched.find_loop("i")
kernel_jacobi_1d_sched = parallelize_loop(kernel_jacobi_1d_sched, loop_i0)

# Parallelize the second sweep over i (A <- B).
loop_i1 = kernel_jacobi_1d_sched.find_loop("i #1")
kernel_jacobi_1d_sched = parallelize_loop(kernel_jacobi_1d_sched, loop_i1)

# Clean up any minor artifacts after scheduling (constant folding, etc.).
kernel_jacobi_1d_sched = simplify(kernel_jacobi_1d_sched)

# Export the scheduled version under the name expected by the C driver.
kernel_jacobi_1d = rename(kernel_jacobi_1d_sched, "kernel_jacobi_1d")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

