		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i + 2) / n;
      B[i] = ((DATA_TYPE) i + 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable tile size for the spatial dimension. This is chosen so that
# a tile of A and B fits comfortably in cache while providing enough
# work per thread. It can be adjusted for a given machine.
BLOCK_I = 1024


@proc
def kernel_jacobi_1d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n] @ DRAM,
    B: DATA_TYPE[n] @ DRAM,
):
    # We update interior points i in [1, n-1) and access A[i-1] and A[i+1]
    # (and similarly for B), so we require at least three points.
    assert n > 2

    for t in seq(0, tsteps):
        # Sweep 1: compute B from the current A.
        # A is read-only in this loop; B[1..n-2] are written exactly once.
        for i in seq(1, n - 1):
            B[i] = 0.33333 * (A[i - 1] + A[i] + A[i + 1])

        # Sweep 2: compute the next A from B.
        # B is read-only in this loop; A[1..n-2] are written exactly once.
        for i in seq(1, n - 1):
            A[i] = 0.33333 * (B[i - 1] + B[i] + B[i + 1])


# Start from the simple baseline kernel and apply a cache- and
# parallel-friendly schedule to obtain the final kernel used by C.
kernel_jacobi_1d_sched = kernel_jacobi_1d_base

# ---------------------------------------------------------------------------
# 1) Tile the spatial loop in the first sweep (B update).
#    This turns:
#       for i in seq(1, n - 1):
#           ...
#    into a two-level loop over tiles I0 and intra-tile index i0. The
#    "guard" tail strategy keeps the full iteration space [1, n-1) while
#    handling any remainder points with conditional guards.
# ---------------------------------------------------------------------------
kernel_jacobi_1d_sched = divide_loop(
    kernel_jacobi_1d_sched,
    "i",                 # first i-loop: B update
    BLOCK_I,             # tile size along i
    ["I0", "i0"],        # outer tile index, inner point index
    tail="guard",
)

# ---------------------------------------------------------------------------
# 2) Tile the spatial loop in the second sweep (A update) in the same way.
#    After the first divide_loop, the remaining i-loop (second sweep) is
#    still named "i", so we apply the same transformation to it.
# ---------------------------------------------------------------------------
kernel_jacobi_1d_sched = divide_loop(
    kernel_jacobi_1d_sched,
    "i",                 # remaining i-loop: A update
    BLOCK_I,
    ["I1", "i1"],
    tail="guard",
)

# ---------------------------------------------------------------------------
# 3) Parallelize across spatial tiles for both sweeps.
#
#    Correctness:
#      - In the B-sweep, each iteration reads only from A (read-only)
#        and writes to a distinct B[i], so different tiles I0 are
#        independent and can run in parallel.
#      - In the A-sweep, each iteration reads only from B (read-only)
#        and writes to a distinct A[i], so different tiles I1 are also
#        independent and can run in parallel.
#      - The overall loop nest structure still executes the entire
#        B-sweep for a given time step t before starting the A-sweep,
#        so the original time-stepping and phase ordering are preserved.
#
#    The parallelize_loop primitive lowers these outer tile loops to
#    OpenMP parallel-for loops by default on C code generation.
# ---------------------------------------------------------------------------
loop_I0 = kernel_jacobi_1d_sched.find_loop("I0")
loop_I1 = kernel_jacobi_1d_sched.find_loop("I1")

kernel_jacobi_1d_sched = parallelize_loop(kernel_jacobi_1d_sched, loop_I0)
kernel_jacobi_1d_sched = parallelize_loop(kernel_jacobi_1d_sched, loop_I1)

# The innermost loops (i0 and i1) now iterate over contiguous segments of
# A and B within a tile. With -O3, the C compiler can automatically
# vectorize these loops using the available SIMD units.

# ---------------------------------------------------------------------------
# 4) Rename the scheduled procedure to the name expected by the C driver.
# ---------------------------------------------------------------------------
kernel_jacobi_1d = rename(kernel_jacobi_1d_sched, "kernel_jacobi_1d")

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 1D views to 1D pointers. */
  kernel_jacobi_1d (/*ctxt=*/NULL,
                    tsteps, n,
                    (DATA_TYPE*)POLYBENCH_ARRAY(A),
                    (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
